js:
const CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/<>_-#%';

// Texto que "decodifica": as letras entram embaralhadas e vão assentando da
// esquerda para a direita. Cada caractere tem um instante para assentar;
// antes disso é sorteado a cada quadro, depois não muda mais.
export function scrambleTo(el, texto, opcoes) {
  const config = opcoes || {};
  const duracao = config.duracao || 520;
  // Quanto do tempo total é gasto assentando letras; o resto é embaralho puro.
  const janela = 0.55;

  if (el._scrambleRaf) cancelAnimationFrame(el._scrambleRaf);

  // Sem movimento: troca seca, sem embaralhar.
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    el.textContent = texto;
    return;
  }

  const inicio = performance.now();
  const assenta = Array.prototype.map.call(texto, function (_, i) {
    return (i / Math.max(texto.length - 1, 1)) * duracao * janela;
  });

  function quadro(agora) {
    const t = agora - inicio;
    let saida = '';
    let pronto = true;

    for (let i = 0; i < texto.length; i++) {
      const c = texto[i];
      if (c === ' ') { saida += ' '; continue; }
      if (t >= assenta[i] + duracao * (1 - janela)) {
        saida += c;
      } else {
        saida += CHARS[(Math.random() * CHARS.length) | 0];
        pronto = false;
      }
    }

    el.textContent = saida;
    if (pronto) { el._scrambleRaf = null; return; }
    el._scrambleRaf = requestAnimationFrame(quadro);
  }

  el._scrambleRaf = requestAnimationFrame(quadro);
}

export function initHeroBadge(palavras) {
  const wordEl = document.getElementById('heroBadgeWord');
  if (!wordEl || palavras.length < 2) return;

  const total = palavras.length;
  let atual = 0;
  let pendente = false;

  function trocar(i) {
    if (i === atual) return;
    atual = i;
    scrambleTo(wordEl, palavras[i]);
  }

  function medir() {
    pendente = false;
    const avanco = Math.min(Math.max(window.scrollY / window.innerHeight, 0), 0.999);
    trocar(Math.floor(avanco * total));
  }

  window.addEventListener('scroll', function () {
    if (window.scrollY > window.innerHeight * 1.2) return;
    if (!pendente) {
      pendente = true;
      requestAnimationFrame(medir);
    }
  }, { passive: true });

  wordEl.textContent = palavras[0];
}
